-- Heroic/Mythic dungeon creature spell damage multipliers (CoADungeonSpellDamage.cpp), keyed by the cast spell tier
-- Generated by dungeon-recherche/spell_schaden.py from boss_test.py measurements: Mythic = Heroic * 1.3,
-- constant boss nukes 600 on Heroic.
CREATE TABLE IF NOT EXISTS `coa_dungeon_spell_damage` (
  `spell_id` int unsigned NOT NULL,
  `multiplier` float NOT NULL DEFAULT 1,
  `comment` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`spell_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `coa_dungeon_spell_damage`;
